"); printf ("{ By ZzagorR - http://www.rootbinbash.com }
"); printf ("{ usage : %s ret buf }
",argv[0]); printf ("{ example : %s 0xbfffff99 142 }
",argv[0]); printf ("{ mandrake 9.2 = 0xbfffff96 }
"); printf ("{ slackware 10.0.0 = 0xbfffff98 }
"); printf ("{ slackware 9.1.0 = 0xbfffff84 }
